#include "find_all_anagrams.hpp"

#include <gtest/gtest.h>


TEST(FindAllAnagrams, SimpleTest1) {
    const std::string str = "cbaebabacd";
    const std::string anagram = "abc";
    std::vector<int> result {0, 6};
    EXPECT_EQ(findAnagrams2(str, anagram), result);
    EXPECT_EQ(findAnagrams3(str, anagram), result);
}

TEST(FindAllAnagrams, SimpleTest2) {
    const std::string str = "aaac";
    const std::string anagram = "aac";
    std::vector<int> result {1};
    EXPECT_EQ(findAnagrams2(str, anagram), result);
    EXPECT_EQ(findAnagrams3(str, anagram), result);
}

TEST(FindAllAnagrams, SimpleTest3) {
    const std::string str = "abab";
    const std::string anagram = "ab";
    std::vector<int> result {0, 1, 2};
    EXPECT_EQ(findAnagrams2(str, anagram), result);
    EXPECT_EQ(findAnagrams3(str, anagram), result);
}

